    "incoming": true,
    "outgoing": true,
    "read": true,
    "label": "string",
    "snoozed_until": "2019-01-01T00:00:00",
    "starred": true,
    "archived": true,
    "spam": true,
    "created_at": "2019-01-01T00:00:00",
    "updated_at": "2019-01-01T00:00:00",
    "subject": "string",
    "participants": [
